#!/usr/bin/env python3
"""Offline campaign CLI; JSON stdin/stdout, diagnostics on stderr.

Reads one UTF-8 JSON campaign from stdin and writes its complete JSON
certificate to stdout.  Framing problems (duplicate keys, non-finite numbers,
invalid UTF-8, malformed JSON, trailing JSON, over-long input) produce exactly
``{"error":"INVALID_INPUT"}`` and exit zero, as does any internal failure.
"""
import json
import math
from pathlib import Path
import sys

sys.setrecursionlimit(6000)
sys.path.insert(0, str(Path(__file__).resolve().parent / "src"))

from eywa.offline import execute  # noqa: E402  (local src bootstrap)

LIMIT = 64 * 1024 * 1024
INVALID = {"error": "INVALID_INPUT"}


def pairs(items):
    d = {}
    for key, value in items:
        if key in d:
            raise ValueError("duplicate key")
        d[key] = value
    return d


def load(raw):
    if len(raw) > LIMIT:
        raise ValueError("input cap")

    def bad(value):
        raise ValueError("nonfinite")

    def finite(value):
        result = float(value)
        if not math.isfinite(result):
            raise ValueError("nonfinite")
        return result

    return json.loads(raw.decode("utf-8"), object_pairs_hook=pairs,
                      parse_constant=bad, parse_float=finite)


def render(result):
    text = json.dumps(result, ensure_ascii=True, separators=(",", ":"),
                      allow_nan=False)
    return text + "\n"


def main():
    try:
        raw = sys.stdin.buffer.read(LIMIT + 1)
        request = load(raw)
    except (ValueError, UnicodeError, RecursionError):
        request = INVALID
    try:
        result = request if isinstance(request, dict) and "error" in request \
            else execute(request)
        text = render(result)
    except BaseException:  # pragma: no cover - never fail the interface
        text = render(INVALID)
    sys.stdout.write(text)
    sys.stdout.flush()


if __name__ == "__main__":
    main()
PYEOF
